using System;using System.Collections.Generic;using UnityEngine;using UnityEngine.Rendering;
namespace FashionFit {
 public static class FittedGarmentGeometry {
  public static Mesh Shell(RunwayAvatar body,bool trousers,bool longSleeves=true){if(!trousers&&!longSleeves)return ContinuousShirtShell.Build(body,false);var vertices=body.BodyVertices;var normals=body.BodyMesh.normals;var weights=body.BodyMesh.boneWeights;var uv=body.BodyMesh.uv;var faces=body.BodyMesh.triangles;float h=body.BodyMesh.bounds.max.y,waist=h*.60f,neck=Neutral(body,"Neck").y;NeckProfile(body,out float collarY,out float collarX,out float collarZ,out float collarCentre);var valid=new bool[vertices.Length];string[] names=Array.ConvertAll(body.Bones,x=>x.name.Replace("mixamorig:",""));
   for(int i=0;i<vertices.Length;i++){var p=vertices[i];var w=weights[i];int bone=w.boneIndex0;if(w.weight1>w.weight0)bone=w.boneIndex1;string n=names[bone];bool arm=n.Contains("Arm"),hand=n.Contains("Hand"),leg=n.Contains("Leg")||n.Contains("Foot");if(trousers)valid[i]=!arm&&!hand&&p.y<=waist+.025f&&p.y>=.07f;else{valid[i]=!hand&&p.y<=(longSleeves?collarY:neck+.025f)&&(arm||p.y>=waist-.105f);if(!longSleeves&&arm){string side=n.StartsWith("Left")?"Left":"Right";Vector3 a=Neutral(body,side+"Arm"),b=Neutral(body,side+"ForeArm");float u=Vector3.Dot(p-a,b-a)/Mathf.Max(.00001f,(b-a).sqrMagnitude);if(n.Contains("ForeArm")||u>.62f)valid[i]=false;}}}
   var map=new Dictionary<int,int>();var v=new List<Vector3>();var t=new List<int>();var tex=new List<Vector2>();var skin=new List<BoneWeight>();
   for(int f=0;f<faces.Length;f+=3){int a=faces[f],b=faces[f+1],c=faces[f+2];if(!valid[a]||!valid[b]||!valid[c])continue;foreach(int index in new[]{a,b,c}){if(!map.TryGetValue(index,out int id)){id=v.Count;map.Add(index,id);Vector3 normal=normals.Length==vertices.Length?normals[index]:new Vector3(vertices[index].x,0,vertices[index].z).normalized;float allowance=trousers ? .036f : names[weights[index].boneIndex0].Contains("Arm") ? .025f : Mathf.Lerp(.065f,.025f,Mathf.InverseLerp(waist-.04f,waist+.12f,vertices[index].y));v.Add(vertices[index]+normal*allowance);tex.Add(uv.Length==vertices.Length?uv[index]:new Vector2(vertices[index].x,vertices[index].y));skin.Add(weights[index]);}t.Add(id);}}
   if(!trousers)SmoothFabricFront(v,t,h);
   if(!trousers)FinishClothEnvelope(v,t,h);
   if(!trousers&&longSleeves){int first=v.Count,neckBone=body.BoneIndex("Neck"),steps=32;float centreZ=collarCentre;for(int row=0;row<3;row++)for(int col=0;col<=steps;col++){float angle=2*Mathf.PI*col/steps;v.Add(new Vector3(Mathf.Sin(angle)*(collarX+.024f),collarY-.010f+row*.014f,centreZ+Mathf.Cos(angle)*(collarZ+.024f)));tex.Add(new Vector2(col/(float)steps,row*.5f));skin.Add(new BoneWeight{boneIndex0=neckBone,weight0=1});if(row>0&&col<steps){int a=first+(row-1)*(steps+1)+col,b=a+1,c=a+steps+1,d=c+1;t.AddRange(new[]{a,b,c,b,d,c});}}}
   var mesh=new Mesh{name=trousers?"Ao dai independent two-leg trousers":"Fitted shoulder and sleeve shell",indexFormat=IndexFormat.UInt32};mesh.SetVertices(v);mesh.SetTriangles(t,0);mesh.SetUVs(0,tex);mesh.boneWeights=skin.ToArray();mesh.bindposes=body.GarmentBindposes;mesh.RecalculateNormals();mesh.RecalculateTangents();mesh.RecalculateBounds();return mesh;
  }
  // A blouse bridges small anatomical details; it must not copy skin bumps
  // as if painted on the body. Collision clearance is solved afterwards.
  static void SmoothFabricFront(List<Vector3> points,List<int> triangles,float height){var neighbors=new List<int>[points.Count];for(int i=0;i<neighbors.Length;i++)neighbors[i]=new List<int>();for(int f=0;f<triangles.Count;f+=3)for(int k=0;k<3;k++){int a=triangles[f+k],b=triangles[f+(k+1)%3];if(!neighbors[a].Contains(b))neighbors[a].Add(b);if(!neighbors[b].Contains(a))neighbors[b].Add(a);}var weight=new float[points.Count];for(int i=0;i<points.Count;i++){Vector3 p=points[i];weight[i]=Mathf.SmoothStep(0,1,Mathf.InverseLerp(height*.65f,height*.70f,p.y))*(1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(height*.80f,height*.84f,p.y)))*(1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(.18f,.27f,Mathf.Abs(p.x))))*Mathf.Clamp01(p.z/.05f);}var next=new Vector3[points.Count];for(int pass=0;pass<24;pass++){for(int i=0;i<points.Count;i++){Vector3 mean=Vector3.zero;foreach(int j in neighbors[i])mean+=points[j];next[i]=neighbors[i].Count>0?Vector3.Lerp(points[i],mean/neighbors[i].Count,.45f*weight[i]):points[i];}for(int i=0;i<points.Count;i++)points[i]=next[i];}for(int i=0;i<points.Count;i++)points[i]+=Vector3.forward*(.012f*weight[i]);}
  static void FinishClothEnvelope(List<Vector3> points,List<int> triangles,float height){
   // A smooth, outward pressure envelope spreads small support peaks instead
   // of tracing skin features into the garment. Body collision remains intact.
   var bins=new Dictionary<Vector2Int,List<int>>();const float cell=.02f;for(int i=0;i<points.Count;i++){var p=points[i];if(p.y<height*.66f||p.y>height*.84f||p.z<.025f||Mathf.Abs(p.x)>.27f)continue;var key=new Vector2Int(Mathf.FloorToInt(p.x/cell),Mathf.FloorToInt(p.y/cell));if(!bins.TryGetValue(key,out var list)){list=new List<int>();bins.Add(key,list);}list.Add(i);}
   var output=points.ToArray();for(int i=0;i<points.Count;i++){var p=points[i];float weight=Mathf.SmoothStep(0,1,Mathf.InverseLerp(height*.66f,height*.71f,p.y))*(1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(height*.79f,height*.84f,p.y)))*(1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(.16f,.26f,Mathf.Abs(p.x))));if(weight<=0||p.z<.025f)continue;var key=new Vector2Int(Mathf.FloorToInt(p.x/cell),Mathf.FloorToInt(p.y/cell));float z=p.z;for(int x=-6;x<=6;x++)for(int y=-6;y<=6;y++)if(bins.TryGetValue(key+new Vector2Int(x,y),out var list))foreach(int j in list){var q=points[j];float d=(q.x-p.x)*(q.x-p.x)+(q.y-p.y)*(q.y-p.y);if(d<.0144f)z=Mathf.Max(z,q.z-d/.38f);}output[i].z=Mathf.Lerp(p.z,z+.010f,weight);}for(int i=0;i<points.Count;i++)points[i]=output[i];
   var edges=new Dictionary<long,int>();for(int f=0;f<triangles.Count;f+=3)for(int k=0;k<3;k++){int a=triangles[f+k],b=triangles[f+(k+1)%3];long key=((long)Mathf.Min(a,b)<<32)|(uint)Mathf.Max(a,b);edges[key]=edges.TryGetValue(key,out int count)?count+1:1;}var boundary=new HashSet<int>();foreach(var pair in edges)if(pair.Value==1){boundary.Add((int)(pair.Key>>32));boundary.Add((int)pair.Key);}float hem=height*.60f-.075f;foreach(int i in boundary){var p=points[i];if(Mathf.Abs(p.x)<.27f&&p.y<height*.64f&&p.y>height*.50f){p.y=hem;points[i]=p;}}
  }
  public static void NeckProfile(RunwayAvatar body,out float y,out float rx,out float rz,out float cz){float h=body.BodyMesh.bounds.max.y,best=float.PositiveInfinity;y=h*.87f;rx=.06f;rz=.055f;cz=0;for(int row=0;row<22;row++){float level=h*(.83f+row*.003f),x=0,low=float.PositiveInfinity,high=float.NegativeInfinity;int count=0;foreach(var p in body.BodyVertices)if(Mathf.Abs(p.y-level)<.008f){x=Mathf.Max(x,Mathf.Abs(p.x));low=Mathf.Min(low,p.z);high=Mathf.Max(high,p.z);count++;}if(count>8&&x<best){best=x;y=level;rx=x;rz=(high-low)*.5f;cz=(high+low)*.5f;}}}
  public static Vector3 Neutral(RunwayAvatar body,string joint)=>body.GarmentBindposes[body.BoneIndex(joint)].inverse.MultiplyPoint3x4(Vector3.zero);
  public static BoneWeight Average(BoneWeight a,BoneWeight b,BoneWeight c){var values=new Dictionary<int,float>();foreach(var w in new[]{a,b,c}){int[] ids={w.boneIndex0,w.boneIndex1,w.boneIndex2,w.boneIndex3};float[] v={w.weight0,w.weight1,w.weight2,w.weight3};for(int i=0;i<4;i++)if(v[i]>0)values[ids[i]]=(values.TryGetValue(ids[i],out float old)?old:0)+v[i];}var sorted=new List<KeyValuePair<int,float>>(values);sorted.Sort((x,y)=>y.Value.CompareTo(x.Value));int[] id=new int[4];float[] f=new float[4];float sum=0;for(int i=0;i<4&&i<sorted.Count;i++){id[i]=sorted[i].Key;f[i]=sorted[i].Value;sum+=f[i];}return new BoneWeight{boneIndex0=id[0],boneIndex1=id[1],boneIndex2=id[2],boneIndex3=id[3],weight0=f[0]/sum,weight1=f[1]/sum,weight2=f[2]/sum,weight3=f[3]/sum};}
 }
}
